css:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body.premium-ux {
  min-height: 100vh;
  height: 100%;
  overflow: hidden;
  color: #FFF;
  background-color: #121519;
  font-family: 'Montserrat', 'Roboto', 'Droid Sans', 'Helvetica Neue', sans-serif;
  margin: 0;
  padding: 0;
}

.premium-ux .ux-app {
  display: grid;
  grid-template-rows: 0rem 1fr 0rem;
  height: 100vh;
}

.premium-ux .ux-main {
  padding: 2rem;
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  perspective: 1px;
  scroll-snap-type: block proximity;
}

.premium-ux .ux-section {
  min-height: calc(100vh - 4rem);
  padding-top: 300px;
  margin-bottom: 250px;
  position: relative;
  transform-style: preserve-3d;
  scroll-snap-align: start;
}

.premium-ux .ux-section__header {
  position: absolute;
  top: 50px;
  left: 0;
  right: 0;
  height: 500px;
  padding: 2rem;
  border-radius: 0.5rem;
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center center;
  text-shadow: 0 0 20px rgba(0, 0, 0, 0.25);
}

.premium-ux .ux-section__header::after {
  content: "";
  display: block;
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.5) 100%);
  border-radius: 0.5rem;
}

.premium-ux .ux-section__title {
  font-size: 3.5rem;
  font-weight: 200;
  margin-bottom: .5rem;
  line-height: 1;
  position: relative;
  z-index: 10;
}

.premium-ux .ux-section__subtitle {
  font-size: 1.2rem;
  position: relative;
  z-index: 10;
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  white-space: nowrap;
  overflow: hidden;
}

.premium-ux .ux-marquee span {
  display: inline-block;
  padding-left: 100%;
  animation: marquee 15s linear infinite;
}

@keyframes marquee {
  0% { transform: translate(0, 0); }
  100% { transform: translate(-100%, 0); }
}

.premium-ux .ux-section__controls {
  display: flex;
  align-items: center;
  position: absolute;
  padding: 0 2rem;
  top: 0;
  left: 0;
  right: 0;
  transform: translateY(-50%);
  z-index: 20;
}

.premium-ux .ux-user {
  margin-left: auto;
  text-align: center;
  padding-top: 2rem;
}

.premium-ux .ux-user__img {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  margin-bottom: .5rem;
  box-shadow: 0 0 38px rgba(0, 0, 0, 0.3);
}

.premium-ux .ux-user__name {
  display: block;
  font-size: 1.5rem;
  font-weight: 200;
}

.premium-ux .ux-section__content {
  position: relative;
  z-index: 1;
  padding: 0 1rem;
}

.premium-ux .ux-boxgrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  grid-auto-rows: minmax(150px, auto);
  grid-gap: 2rem .5rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.premium-ux .ux-boxgrid__item {
  display: flex;
}

.premium-ux .ux-boxgrid__item--wide {
  grid-column: span 2;
}

.premium-ux .ux-box {
  display: flex;
  flex: 1 0 0;
  position: relative;
  padding: 2rem;
  border-radius: 0.5rem;
  font-size: .875rem;
  color: #FFF;
  box-shadow: 0 19px 38px rgba(0, 0, 0, 0.3), 0 15px 12px rgba(0, 0, 0, 0.22);
  transform: scale(1);
  transition: all .25s ease;
  filter: brightness(100%);
  overflow: hidden;
  text-decoration: none;
}

.premium-ux .ux-box:hover {
  transform: scale(1.07);
  filter: brightness(110%);
  z-index: 10;
}

.premium-ux .ux-box--image,
.premium-ux .ux-box--video {
  padding: 0;
}

.premium-ux .ux-box__img {
  display: block;
  width: 100%;
  height: 100%;
  position: absolute;
  object-fit: cover;
  object-position: center;
  border-radius: 0.5rem;
  top: 0;
  left: 0;
}

.premium-ux .ux-box--video::before,
.premium-ux .ux-box--video::after {
  content: "";
  display: block;
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 10;
  transform: translate(-50%, -50%);
}

.premium-ux .ux-box--video::before {
  width: 50px;
  height: 50px;
  background-color: #FFF;
  border-radius: 50%;
  box-shadow: 0 0 38px rgba(0, 0, 0, 0.3);
}

.premium-ux .ux-box--video::after {
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 10px 0 10px 15px;
  border-color: transparent transparent transparent #121519;
  margin-left: 2px;
}

.premium-ux .ux-box--embed {
  padding: 0;
  background: #1a1a1a;
}

.premium-ux .ux-box--embed iframe {
  width: 100%;
  height: 100%;
  border: none;
  border-radius: 0.5rem;
}

.premium-ux .ux-text--large {
  font-size: 2rem;
  font-weight: 200;
}

@media screen and (min-width: 1024px) {
  .premium-ux .ux-section {
    margin-bottom: 750px;
  }
  .premium-ux .ux-section__header {
    transform: translateZ(-1px) scale(1.9);
  }
  .premium-ux .ux-section__content {
    padding: 0;
    transform: translateZ(0);
  }
  .premium-ux .ux-boxgrid__item--push {
    grid-column: span 2;
    padding-left: 50%;
  }
}

